#include "tls_internal.h"

static uint32_t ror32(uint32_t x, unsigned n) { return (x >> n) | (x << (32u - n)); }
static uint32_t load32(const uint8_t *p) { return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; }
static void store32(uint8_t *p, uint32_t x) { p[0]=(uint8_t)(x>>24); p[1]=(uint8_t)(x>>16); p[2]=(uint8_t)(x>>8); p[3]=(uint8_t)x; }
static void store64(uint8_t *p, uint64_t x) { unsigned i; for (i=0;i<8;i++) p[7-i]=(uint8_t)(x>>(i*8)); }

static void sha_block(struct tls_sha256 *c, const uint8_t *p) {
    static const uint32_t k[64] = {
        0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
        0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
        0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
        0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
        0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
        0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
        0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
        0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u };
    uint32_t w[64],a,b,cc,d,e,f,g,h,t1,t2; unsigned i;
    for(i=0;i<16;i++) w[i]=load32(p+4*i);
    for(i=16;i<64;i++) { uint32_t s0=ror32(w[i-15],7)^ror32(w[i-15],18)^(w[i-15]>>3); uint32_t s1=ror32(w[i-2],17)^ror32(w[i-2],19)^(w[i-2]>>10); w[i]=w[i-16]+s0+w[i-7]+s1; }
    a=c->state[0];b=c->state[1];cc=c->state[2];d=c->state[3];e=c->state[4];f=c->state[5];g=c->state[6];h=c->state[7];
    for(i=0;i<64;i++) { uint32_t S1=ror32(e,6)^ror32(e,11)^ror32(e,25); uint32_t ch=(e&f)^((~e)&g); t1=h+S1+ch+k[i]+w[i]; uint32_t S0=ror32(a,2)^ror32(a,13)^ror32(a,22); uint32_t maj=(a&b)^(a&cc)^(b&cc); t2=S0+maj; h=g;g=f;f=e;e=d+t1;d=cc;cc=b;b=a;a=t1+t2; }
    c->state[0]+=a;c->state[1]+=b;c->state[2]+=cc;c->state[3]+=d;c->state[4]+=e;c->state[5]+=f;c->state[6]+=g;c->state[7]+=h;
}

void tls_sha256_init(struct tls_sha256 *c) { c->state[0]=0x6a09e667u;c->state[1]=0xbb67ae85u;c->state[2]=0x3c6ef372u;c->state[3]=0xa54ff53au;c->state[4]=0x510e527fu;c->state[5]=0x9b05688cu;c->state[6]=0x1f83d9abu;c->state[7]=0x5be0cd19u;c->total=0;c->used=0; }
void tls_sha256_update(struct tls_sha256 *c, const void *data, size_t n) { const uint8_t *p=(const uint8_t *)data; c->total+=(uint64_t)n; while(n) { size_t q=64-c->used; if(q>n) q=n; { size_t i; for(i=0;i<q;i++) c->block[c->used+i]=p[i]; } c->used+=q;p+=q;n-=q; if(c->used==64){sha_block(c,c->block);c->used=0;} } }
void tls_sha256_final(struct tls_sha256 *c, uint8_t out[32]) { uint64_t bits=c->total*8; size_t i; c->block[c->used++]=0x80; while(c->used!=56){if(c->used==64){sha_block(c,c->block);c->used=0;} c->block[c->used++]=0;} store64(c->block+56,bits);sha_block(c,c->block);for(i=0;i<8;i++) store32(out+4*i,c->state[i]); }

void tls_hmac_sha256(const uint8_t *key,size_t kl,const uint8_t *data,size_t dl,uint8_t out[32]) { uint8_t k[64],ipad[64],opad[64],tmp[32]; struct tls_sha256 c; size_t i; for(i=0;i<64;i++) k[i]=0; if(kl>64){tls_sha256_init(&c);tls_sha256_update(&c,key,kl);tls_sha256_final(&c,k); } else for(i=0;i<kl;i++) k[i]=key[i]; for(i=0;i<64;i++){ipad[i]=k[i]^0x36;opad[i]=k[i]^0x5c;} tls_sha256_init(&c);tls_sha256_update(&c,ipad,64);tls_sha256_update(&c,data,dl);tls_sha256_final(&c,tmp);tls_sha256_init(&c);tls_sha256_update(&c,opad,64);tls_sha256_update(&c,tmp,32);tls_sha256_final(&c,out); }
void tls_prf_sha256(const uint8_t *secret,size_t sl,const char *label,const uint8_t *seed,size_t zl,uint8_t *out,size_t ol) { uint8_t a[32],block[32],buf[512]; size_t ll=0,off=0,i; while(label[ll]) ll++; tls_hmac_sha256(secret,sl,(const uint8_t *)label,ll, a); { uint8_t x[512]; if(ll+zl>sizeof(x)) return; for(i=0;i<ll;i++) x[i]=(uint8_t)label[i];for(i=0;i<zl;i++)x[ll+i]=seed[i];tls_hmac_sha256(secret,sl,x,ll+zl,a); } while(off<ol){ size_t n,bl=ll+zl+32; if(bl>sizeof(buf)) return; for(i=0;i<32;i++) buf[i]=a[i];for(i=0;i<ll;i++)buf[32+i]=(uint8_t)label[i];for(i=0;i<zl;i++)buf[32+ll+i]=seed[i];tls_hmac_sha256(secret,sl,buf,bl,block);n=ol-off;if(n>32)n=32;for(i=0;i<n;i++)out[off+i]=block[i];off+=n;tls_hmac_sha256(secret,sl,a,32,a); } }

static uint8_t sbox(uint8_t x){ static const uint8_t s[256]={0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16}; return s[x]; }
static uint8_t gm2(uint8_t x){return (uint8_t)((x<<1)^((x>>7)*0x1b));}
void tls_aes128_init(struct tls_aes128 *c,const uint8_t key[16]){unsigned i;uint8_t t[4];static const uint8_t r[10]={1,2,4,8,16,32,64,128,27,54};for(i=0;i<16;i++)c->round_keys[i]=key[i];for(i=16;i<176;i+=4){t[0]=c->round_keys[i-4];t[1]=c->round_keys[i-3];t[2]=c->round_keys[i-2];t[3]=c->round_keys[i-1];if(i%16==0){uint8_t q=t[0];t[0]=sbox(t[1])^(r[i/16-1]);t[1]=sbox(t[2]);t[2]=sbox(t[3]);t[3]=sbox(q);}c->round_keys[i]=c->round_keys[i-16]^t[0];c->round_keys[i+1]=c->round_keys[i-15]^t[1];c->round_keys[i+2]=c->round_keys[i-14]^t[2];c->round_keys[i+3]=c->round_keys[i-13]^t[3];}}
void tls_aes128_encrypt(const struct tls_aes128 *c,const uint8_t in[16],uint8_t out[16]){uint8_t s[16],t[16];unsigned i,r;for(i=0;i<16;i++)s[i]=in[i]^c->round_keys[i];for(r=1;r<=10;r++){for(i=0;i<16;i++)t[i]=sbox(s[i]);s[0]=t[0];s[1]=t[5];s[2]=t[10];s[3]=t[15];s[4]=t[4];s[5]=t[9];s[6]=t[14];s[7]=t[3];s[8]=t[8];s[9]=t[13];s[10]=t[2];s[11]=t[7];s[12]=t[12];s[13]=t[1];s[14]=t[6];s[15]=t[11];if(r!=10){for(i=0;i<4;i++){uint8_t a=s[4*i],b=s[4*i+1],d=s[4*i+2],e=s[4*i+3];s[4*i]=gm2(a)^(gm2(b)^b)^d^e;s[4*i+1]=a^gm2(b)^(gm2(d)^d)^e;s[4*i+2]=a^b^gm2(d)^(gm2(e)^e);s[4*i+3]=(gm2(a)^a)^b^d^gm2(e);}}for(i=0;i<16;i++)s[i]^=c->round_keys[16*r+i];}for(i=0;i<16;i++)out[i]=s[i];}

static void gmul(const uint8_t *x,const uint8_t *y,uint8_t *z){uint8_t v[16],r[16];unsigned i,j;for(i=0;i<16;i++){v[i]=y[i];r[i]=0;}for(i=0;i<128;i++){unsigned bit=(x[i>>3]>>(7-(i&7)))&1u;for(j=0;j<16;j++)r[j]^=(uint8_t)(v[j]&(-(int)bit));{unsigned lsb=v[15]&1;for(j=15;j>0;j--)v[j]=(uint8_t)((v[j]>>1)|(v[j-1]<<7));v[0]>>=1;v[0]^=(uint8_t)(0xe1u&(-(int)lsb));}}for(i=0;i<16;i++)z[i]=r[i];}
static void ghash_full(const uint8_t *h,const uint8_t *aad,size_t al,const uint8_t *ct,size_t cl,uint8_t *out){uint8_t y[16],b[16];size_t n,i;uint64_t albits=(uint64_t)al*8,clbits=(uint64_t)cl*8;for(i=0;i<16;i++)y[i]=0;while(al){n=al<16?al:16;for(i=0;i<16;i++)b[i]=0;for(i=0;i<n;i++)b[i]=aad[i];for(i=0;i<16;i++)y[i]^=b[i];gmul(y,h,y);aad+=n;al-=n;}while(cl){n=cl<16?cl:16;for(i=0;i<16;i++)b[i]=0;for(i=0;i<n;i++)b[i]=ct[i];for(i=0;i<16;i++)y[i]^=b[i];gmul(y,h,y);ct+=n;cl-=n;}store64(b,albits);store64(b+8,clbits);for(i=0;i<16;i++)y[i]^=b[i];gmul(y,h,y);for(i=0;i<16;i++)out[i]=y[i];}
static void ctr(const struct tls_aes128 *c,const uint8_t j0[16],const uint8_t *in,size_t n,uint8_t *out){uint8_t x[16],ks[16];uint32_t v=load32(j0+12);size_t i;while(n){v++;for(i=0;i<16;i++)x[i]=j0[i];store32(x+12,v);tls_aes128_encrypt(c,x,ks);for(i=0;i<16&&n;i++,n--)out[i]=in[i]^ks[i];in+=i;out+=i;}}
static int gcm_tag(const struct tls_aes128 *c,const uint8_t iv[4],const uint8_t nonce[8],const uint8_t *aad,size_t al,const uint8_t *ct,size_t cl,uint8_t tag[16]){uint8_t j[16],h[16],s[16],e[16];size_t i;for(i=0;i<4;i++)j[i]=iv[i];for(i=0;i<8;i++)j[4+i]=nonce[i];j[12]=0;j[13]=0;j[14]=0;j[15]=1;for(i=0;i<16;i++)h[i]=0;tls_aes128_encrypt(c,h,h);ghash_full(h,aad,al,ct,cl,s);tls_aes128_encrypt(c,j,e);for(i=0;i<16;i++)tag[i]=e[i]^s[i];return 1;}
int tls_aes128_gcm_encrypt(const struct tls_aes128 *c,const uint8_t iv[4],const uint8_t nonce[8],const uint8_t *aad,size_t al,const uint8_t *in,size_t n,uint8_t *out,uint8_t tag[16]){uint8_t j[16];size_t i;for(i=0;i<4;i++)j[i]=iv[i];for(i=0;i<8;i++)j[4+i]=nonce[i];j[12]=0;j[13]=0;j[14]=0;j[15]=1;for(i=0;i<n;i++)out[i]=in[i];ctr(c,j,in,n,out);gcm_tag(c,iv,nonce,aad,al,out,n,tag);return 1;}
int tls_aes128_gcm_decrypt(const struct tls_aes128 *c,const uint8_t iv[4],const uint8_t nonce[8],const uint8_t *aad,size_t al,const uint8_t *in,size_t n,const uint8_t tag[16],uint8_t *out){uint8_t want[16];size_t i;for(i=0;i<n;i++)out[i]=in[i];gcm_tag(c,iv,nonce,aad,al,in,n,want);{uint8_t diff=0;for(i=0;i<16;i++)diff|=want[i]^tag[i];if(diff){for(i=0;i<n;i++)out[i]=0;return 0;}}{uint8_t j[16];for(i=0;i<4;i++)j[i]=iv[i];for(i=0;i<8;i++)j[4+i]=nonce[i];j[12]=0;j[13]=0;j[14]=0;j[15]=1;ctr(c,j,in,n,out);}return 1;}

typedef int64_t gf25519[16];
static const gf25519 gf121665={0xdb41,1};
static void gf_copy(gf25519 o,const gf25519 a){unsigned i;for(i=0;i<16;i++)o[i]=a[i];}
static void gf_add(gf25519 o,const gf25519 a,const gf25519 b){unsigned i;for(i=0;i<16;i++)o[i]=a[i]+b[i];}
static void gf_sub(gf25519 o,const gf25519 a,const gf25519 b){unsigned i;for(i=0;i<16;i++)o[i]=a[i]-b[i];}
static void gf_carry(gf25519 o){int64_t c;unsigned i;for(i=0;i<16;i++){o[i]+=65536;c=o[i]>>16;if(i<15)o[i+1]+=c-1;else o[0]+=38*(c-1);o[i]-=c*65536;}}
static void gf_select(gf25519 p,gf25519 q,int bit){int64_t mask=~(int64_t)(bit-1),t;unsigned i;for(i=0;i<16;i++){t=mask&(p[i]^q[i]);p[i]^=t;q[i]^=t;}}
static void gf_pack(uint8_t out[32],const gf25519 n){gf25519 m,t;int64_t b;unsigned i,j;gf_copy(t,n);gf_carry(t);gf_carry(t);gf_carry(t);for(j=0;j<2;j++){m[0]=t[0]-0xffed;for(i=1;i<15;i++){m[i]=t[i]-0xffff-((m[i-1]>>16)&1);m[i-1]&=0xffff;}m[15]=t[15]-0x7fff-((m[14]>>16)&1);b=(m[15]>>16)&1;m[14]&=0xffff;gf_select(t,m,(int)(1-b));}for(i=0;i<16;i++){out[2*i]=(uint8_t)t[i];out[2*i+1]=(uint8_t)(t[i]>>8);}}
static void gf_unpack(gf25519 o,const uint8_t in[32]){unsigned i;for(i=0;i<16;i++)o[i]=(int64_t)in[2*i]+((int64_t)in[2*i+1]<<8);o[15]&=0x7fff;}
static void gf_mul(gf25519 o,const gf25519 a,const gf25519 b){int64_t t[31]={0};unsigned i,j;for(i=0;i<16;i++)for(j=0;j<16;j++)t[i+j]+=a[i]*b[j];for(i=0;i<15;i++)t[i]+=38*t[i+16];for(i=0;i<16;i++)o[i]=t[i];gf_carry(o);gf_carry(o);}
static void gf_square(gf25519 o,const gf25519 a){gf_mul(o,a,a);}
static void gf_inverse(gf25519 o,const gf25519 in){gf25519 c;int i;gf_copy(c,in);for(i=253;i>=0;i--){gf_square(c,c);if(i!=2&&i!=4)gf_mul(c,c,in);}gf_copy(o,c);}
int tls_x25519(uint8_t out[32],const uint8_t scalar[32],const uint8_t point[32]){gf25519 x,a,b,c,d,e,f;uint8_t z[32];int i,r;uint8_t nz=0;for(i=0;i<32;i++)z[i]=scalar[i];z[0]&=248;z[31]=(uint8_t)((z[31]&127)|64);gf_unpack(x,point);for(i=0;i<16;i++){b[i]=x[i];a[i]=0;c[i]=0;d[i]=0;}a[0]=1;d[0]=1;for(i=254;i>=0;i--){r=(z[i>>3]>>(i&7))&1;gf_select(a,b,r);gf_select(c,d,r);gf_add(e,a,c);gf_sub(a,a,c);gf_add(c,b,d);gf_sub(b,b,d);gf_square(d,e);gf_square(f,a);gf_mul(a,c,a);gf_mul(c,b,e);gf_add(e,a,c);gf_sub(a,a,c);gf_square(b,a);gf_sub(c,d,f);gf_mul(a,c,gf121665);gf_add(a,a,d);gf_mul(c,c,a);gf_mul(a,d,f);gf_mul(d,b,x);gf_square(b,e);gf_select(a,b,r);gf_select(c,d,r);}gf_inverse(c,c);gf_mul(a,a,c);gf_pack(out,a);for(i=0;i<32;i++)nz|=out[i];return nz?0:-1;}

static int cpuid_rdrand(void){uint32_t a,b,c,d;uint32_t max;__asm__ volatile("cpuid":"=a"(max),"=b"(b),"=c"(c),"=d"(d):"a"(0));if(max<1)return 0;__asm__ volatile("cpuid":"=a"(a),"=b"(b),"=c"(c),"=d"(d):"a"(1),"c"(0));return (int)((c>>30)&1u);}
int tls_random_bytes(uint8_t *out,size_t n){uint32_t x;unsigned char ok;size_t i;if(!cpuid_rdrand())return 1;while(n){__asm__ volatile(".byte 0x0f,0xc7,0xf0; setc %1":"=a"(x),"=qm"(ok)::"cc");if(!ok)return 1;for(i=0;i<4&&n;i++,n--){*out++=(uint8_t)x;x>>=8;}}return 0;}
